// Purpose: every chapter's stage, in story order, and a way to find one by its chapter.
// Generated by rules_dotnet/tools/export_chapters.js from prototype/web/js/levels.js.
// Don't edit by hand: change levels.js and run the tool again.
namespace Bodhi.Game
{
    public static partial class ChapterStages
    {
        // Makes a fresh copy of every stage, first to last.
        public static ChapterStage[] all()
        {
            return new[]
            {
                coming_home(),
                the_storm(),
                last_morning(),
                other_side(),
                motorway(),
                visiting_hours(),
                orchard(),
                lessons(),
                first_snow(),
                crossing(),
                high_farm(),
                home(),
            };
        }

        // The stage for the chapter with this id, or null if there is none.
        public static ChapterStage for_chapter(string chapter_id)
        {
            switch (chapter_id)
            {
                case "coming_home": return coming_home();
                case "the_storm": return the_storm();
                case "last_morning": return last_morning();
                case "other_side": return other_side();
                case "motorway": return motorway();
                case "visiting_hours": return visiting_hours();
                case "orchard": return orchard();
                case "lessons": return lessons();
                case "first_snow": return first_snow();
                case "crossing": return crossing();
                case "high_farm": return high_farm();
                case "home": return home();
                default: return null;
            }
        }
    }
}
